files.content:
[hidden] { display: none !important; }

*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 18px;
  line-height: 1.5;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: #1a1a2e;
  color: #e0e0e0;
  padding: 1rem;
}

.card {
  background: #16213e;
  border-radius: 1.5rem;
  padding: 2rem;
  width: 100%;
  max-width: 480px;
  text-align: center;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.4);
}

h1 {
  font-size: 1.75rem;
  margin-bottom: 1.5rem;
  color: #e94560;
  font-weight: 700;
  letter-spacing: 0.02em;
}

.controls {
  display: flex;
  flex-direction: column;
  gap: 1rem;
  margin-bottom: 1.5rem;
}

.input-group {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 0.25rem;
}

label {
  font-size: 1rem;
  font-weight: 600;
  color: #a0a0b0;
}

input[type="number"] {
  width: 100%;
  padding: 0.6rem 0.75rem;
  font-size: 1.1rem;
  border: 2px solid #2a2a4a;
  border-radius: 0.75rem;
  background: #0f0f1a;
  color: #e0e0e0;
  transition: border-color 0.2s;
}

input[type="number"]:focus {
  outline: none;
  border-color: #e94560;
  box-shadow: 0 0 0 3px rgba(233, 69, 96, 0.3);
}

.start-btn {
  width: 100%;
  padding: 0.85rem;
  font-size: 1.25rem;
  font-weight: 700;
  border: none;
  border-radius: 0.75rem;
  background: #e94560;
  color: #fff;
  cursor: pointer;
  transition: background 0.2s, transform 0.1s;
  margin-bottom: 1.5rem;
}

.start-btn:hover:not(:disabled) {
  background: #c73650;
}

.start-btn:focus-visible {
  outline: 3px solid #e94560;
  outline-offset: 3px;
}

.start-btn:active:not(:disabled) {
  transform: scale(0.97);
}

.start-btn:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

.display {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

.phase {
  font-size: 1.5rem;
  font-weight: 700;
  color: #e94560;
  text-transform: uppercase;
  letter-spacing: 0.1em;
}

.round {
  font-size: 1.2rem;
  color: #a0a0b0;
}

.time {
  font-size: 3rem;
  font-weight: 800;
  font-variant-numeric: tabular-nums;
  color: #e0e0e0;
  line-height: 1.2;
}

.completion {
  font-size: 1.5rem;
  font-weight: 700;
  color: #4ecca3;
  margin-top: 1rem;
}

@media (max-width: 400px) {
  .card {
    padding: 1.5rem;
  }
  h1 {
    font-size: 1.5rem;
  }
  .time {
    font-size: 2.5rem;
  }
}

const workInput = document.getElementById('workSeconds');
const restInput = document.getElementById('restSeconds');
const roundsInput = document.getElementById('rounds');
const startBtn = document.getElementById('startBtn');
const phaseDisplay = document.getElementById('phaseDisplay');
const roundDisplay = document.getElementById('roundDisplay');
const timeDisplay = document.getElementById('timeDisplay');
const completionMessage = document.getElementById('completionMessage');

let timer = null;
let currentPhase = 'work';
let currentRound = 1;
let remaining = 0;
let totalRounds = 0;
let workSeconds = 0;
let restSeconds = 0;

function updateDisplay() {
  phaseDisplay.textContent = currentPhase === 'work' ? 'Work' : 'Rest';
  roundDisplay.textContent = `Round: ${currentRound} / ${totalRounds}`;
  timeDisplay.textContent = remaining;
}

function tick() {
  remaining--;
  if (remaining <= 0) {
    if (currentPhase === 'work') {
      currentPhase = 'rest';
      remaining = restSeconds;
    } else {
      if (currentRound >= totalRounds) {
        finishWorkout();
        return;
      }
      currentRound++;
      currentPhase = 'work';
      remaining = workSeconds;
    }
  }
  updateDisplay();
}

function finishWorkout() {
  clearInterval(timer);
  timer = null;
  phaseDisplay.textContent = 'Done';
  roundDisplay.textContent = '';
  timeDisplay.textContent = '';
  completionMessage.hidden = false;
  startBtn.disabled = false;
  startBtn.textContent = 'Start';
}

function startWorkout() {
  workSeconds = parseInt(workInput.value, 10);
  restSeconds = parseInt(restInput.value, 10);
  totalRounds = parseInt(roundsInput.value, 10);

  if (!workSeconds || workSeconds < 1 || !restSeconds || restSeconds < 1 || !totalRounds || totalRounds < 1) {
    alert('Please enter positive numbers for work, rest, and rounds.');
    return;
  }

  currentPhase = 'work';
  currentRound = 1;
  remaining = workSeconds;
  completionMessage.hidden = true;
  startBtn.disabled = true;
  startBtn.textContent = 'Running...';
  updateDisplay();

  timer = setInterval(tick, 1000);
}

startBtn.addEventListener('click', startWorkout);
